def is_point_on_segment(p, a, b):
    # Check if p lies on the line segment from a to b
    # First, check if the cross product is zero (collinear)
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if p is collinear with a and b
    if cross(a, b, p) != 0:
        return False

    # Check if p lies between a and b (inclusive)
    def dot(v, w):
        return v[0] * w[0] + v[1] * w[1]

    def length(v):
        return (v[0] ** 2 + v[1] ** 2) ** 0.5

    def distance(a, b):
        return length((a[0] - b[0], a[1] - b[1]))

    # Vector from a to b
    ab = (b[0] - a[0], b[1] - a[1])
    # Vector from a to p
    ap = (p[0] - a[0], p[1] - a[1])

    # Check if the dot product of ab and ap is between 0 and the square of the length of ab
    # This ensures p is between a and b (inclusive)
    dot_product = dot(ab, ap)
    if dot_product < 0 or dot_product > dot(ab, ab):
        return False

    return True
```

