def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    prev = cross(points[-1], points[0], points[1])
    for i in range(1, n):
        curr = cross(points[i-1], points[i], points[(i+1)%n])
        if curr * prev < 0:
            return False
        prev = curr
    return True
```

