def is_convex_polygon(points):
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check all consecutive triplets of points
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        if cross(a, b, c) == 0:
            return False  # Collinear points make it non-convex

        sign = cross(a, b, c)
        for j in range(i + 1, n):
            a2 = points[j]
            b2 = points[(j + 1) % n]
            c2 = points[(j + 2) % n]
            if cross(a2, b2, c2) * sign < 0:
                return False  # Sign change means non-convex

    return True
```

