def is_square(p1, p2, p3, p4):
    def dist_sq(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    points = [p1, p2, p3, p4]
    distances = []
    for i in range(4):
        distances.append(dist_sq(points[i], points[(i + 1) % 4]))
        distances.append(dist_sq(points[i], points[(i + 2) % 4]))

    # There should be exactly 2 distinct distances: 4 sides of equal length and 2 diagonals of equal length
    unique_distances = set(distances)
    return len(unique_distances) == 2 and min(unique_distances) * 2 == max(unique_distances)
```

