import math

def is_square(p1, p2, p3, p4):
    def distance(p, q):
        return math.hypot(p[0] - q[0], p[1] - q[1])

    def is_right_angle(a, b, c):
        # Check if angle at b is a right angle
        return math.isclose(distance(a, b)**2 + distance(b, c)**2, distance(a, c)**2, rel_tol=1e-9)

    def is_equal_length(a, b, c, d):
        # Check if all four sides are equal
        return (math.isclose(distance(a, b), distance(b, c), rel_tol=1e-9) and
                math.isclose(distance(b, c), distance(c, d), rel_tol=1e-9) and
                math.isclose(distance(c, d), distance(d, a), rel_tol=1e-9))

    def is_diagonal_equal(a, b, c, d):
        # Check if both diagonals are equal
        return math.isclose(distance(a, c), distance(b, d), rel_tol=1e-9)

    # Check all four sides are equal and all four angles are right angles
    points = [p1, p2, p3, p4]
    for i in range(4):
        a, b, c = points[i], points[(i+1)%4], points[(i+2)%4]
        if not is_right_angle(a, b, c):
            return False
    return is_equal_length(p1, p2, p3, p4) and is_diagonal_equal(p1, p2, p3, p4)
```

