        return []
    rows, cols = len(grid), len(grid[0])
    result = []
    for i in range(rows + cols - 1):
        row = i
        col = cols - 1 - (i - (rows - 1))
        if 0 <= row < rows and 0 <= col < cols:
            result.append(grid[row][col])
    return result
