def equal_under_rotation(grid1, grid2):
    def rotate(grid):
        n = len(grid)
        return [[grid[n - j - 1][i] for j in range(n)] for i in range(n)]

    def is_equal(g1, g2):
        return g1 == g2

    for _ in range(4):
        if is_equal(grid1, grid2):
            return True
        grid1 = rotate(grid1)
    return False
```

