def count_paths(grid):
    from functools import lru_cache

    m, n = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    @lru_cache(maxsize=None)
    def dfs(i, j):
        if i == m - 1 and j == n - 1:
            return 1
        total = 0
        if i + 1 < m and grid[i+1][j] == 0:
            total += dfs(i+1, j)
        if j + 1 < n and grid[i][j+1] == 0:
            total += dfs(i, j+1)
        return total

    return dfs(0, 0)
```

