def parse_url_parts(url):
    # Split the URL into the scheme and the rest
    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url

    # Split the rest into host and the remaining parts
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        remaining = rest[host_end:]
        if remaining.startswith('/'):
            path = remaining
            query = ''
        elif remaining.startswith('?'):
            path = ''
            query = remaining[1:]
        else:
            path = remaining
            query = ''

    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

