def parse_url_parts(url):
    if '://' not in url:
        raise ValueError("URL must contain a scheme (e.g., 'http://')")

    scheme, rest = url.split('://', 1)
    if '?' in rest:
        host_part, query = rest.split('?', 1)
    else:
        host_part = rest
        query = ''

    if '/' in host_part:
        host, path = host_part.split('/', 1)
        path = '/' + path
    else:
        host = host_part
        path = ''

