def traffic_light_state(n_ticks, durations):
    total_ticks = sum(durations)
    red_ticks, green_ticks, yellow_ticks = durations
    # Determine which phase the tick falls into
    if n_ticks < red_ticks:
        return "RED"
    elif n_ticks < red_ticks + green_ticks:
        return "GREEN"
    elif n_ticks < red_ticks + green_ticks + yellow_ticks:
        return "YELLOW"
    else:
        # Wrap around to the start of the cycle
        return traffic_light_state(n_ticks % total_ticks, durations)
```

