def robot_grid_position(commands):
    # Initial position and direction
    x, y = 0, 0
    facing = "N"

    # Mapping of directions to their effects on x and y
    direction_map = {
        "N": (0, 1),
        "S": (0, -1),
        "E": (1, 0),
        "W": (-1, 0)
    }

    # Process each command
    for cmd in commands:
        if cmd == "L":
            # Counter-clockwise turn
            if facing == "N":
                facing = "W"
            elif facing == "W":
                facing = "S"
            elif facing == "S":
                facing = "E"
            elif facing == "E":
                facing = "N"
        elif cmd == "R":
            # Clockwise turn
            if facing == "N":
                facing = "E"
            elif facing == "E":
                facing = "S"
            elif facing == "S":
                facing = "W"
            elif facing == "W":
                facing = "N"
        elif cmd == "F":
            dx, dy = direction_map[facing]
            x += dx
            y += dy

    return (x, y, facing)
```

