def robot_grid_position(commands):
    # Initial position and direction
    x, y = 0, 0
    facing = 'N'

    # Define direction changes for left and right turns
    direction_order = ['N', 'E', 'S', 'W']
    for cmd in commands:
        if cmd == 'L':
            # Turn left (counter-clockwise)
            facing = direction_order[(direction_order.index(facing) - 1) % 4]
        elif cmd == 'R':
            # Turn right (clockwise)
            facing = direction_order[(direction_order.index(facing) + 1) % 4]
        elif cmd == 'F':
            # Move forward
            if facing == 'N':
                y += 1
            elif facing == 'S':
                y -= 1
            elif facing == 'E':
                x += 1
            elif facing == 'W':
                x -= 1
    return (x, y, facing)
