def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    for t in timestamps:
        count = 0
        for prev_t in timestamps:
            if prev_t > t - window:
                count += 1
        allowed.append(count <= limit)
    return allowed
```

```python
def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    for t in timestamps:
        count = 0
        for prev_t in timestamps:
            if t - window < prev_t <= t:
                count += 1
            if prev_t <= t - window:
                break  # No need to check further as timestamps are non-decreasing
        allowed.append(count <= limit)
    return allowed
```

