    direction = "N"
    cleaned = set((x, y))
    obstacles_set = set(obstacles)

    # Direction mappings
    directions = {
        "N": (0, 1),
        "E": (1, 0),
        "S": (0, -1),
        "W": (-1, 0)
    }

    # Rotation mappings
    rotation = {
        "N": {"L": "W", "R": "E"},
        "E": {"L": "N", "R": "S"},
        "S": {"L": "E", "R": "W"},
        "W": {"L": "S", "R": "N"}
    }

    for cmd in commands:
        if cmd == "L" or cmd == "R":
            direction = rotation[direction][cmd]
        elif cmd == "F":
            dx, dy = directions[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacles_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
