        if current_tick % (red_duration + green_duration) < red_duration:
            # Light is red
            for i, arrival in enumerate(arrivals):
                if arrival <= current_tick and arrival not in crossing_ticks:
                    crossing_ticks.append(current_tick)
                    del arrivals[i]
                    break
        current_tick += 1
    return crossing_ticks
