def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Check if start_floor is requested and add it to the stops
    stops = [start_floor] if start_floor in requests else []
    current_floor = start_floor
    # Create a set for faster lookups
    request_set = set(requests)

    # Determine the stopping condition based on direction
    while True:
        if direction == 1:
            next_floor = current_floor + 1
            if next_floor > top_floor:
                break
        else:
            next_floor = current_floor - 1
            if next_floor < 1:
