    if direction == 1:
        # Moving up
        for floor in range(start_floor + 1, top_floor + 1):
            if floor in requests:
                stops.append(floor)
    else:
        # Moving down
        for floor in range(start_floor - 1, 0, -1):
            if floor in requests:
                stops.append(floor)

    return stops
