def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def get_light_state(tick, durations):
        red, green, yellow = durations
        cycle_length = red + green + yellow
        tick_in_cycle = tick % cycle_length
        if tick_in_cycle < red:
            return 'RED'
        elif tick_in_cycle < red + green:
            return 'GREEN'
        elif tick_in_cycle < red + green + yellow:
            return 'YELLOW'
        else:
            return 'RED'

    count = 0
    for t in range(n_ticks):
        if get_light_state(t, durations_a) == 'GREEN' and get_light_state(t, durations_b) == 'GREEN':
            count += 1
    return count
```

