import math

def classify_triangle_by_sides(p1, p2, p3):
    def distance(p, q):
        return math.hypot(p[0] - q[0], p[1] - q[1])

    d1 = distance(p1, p2)
    d2 = distance(p2, p3)
    d3 = distance(p3, p1)

    sides = sorted([d1, d2, d3])

    if sides[0] == sides[1] == sides[2]:
        return 'equilateral'
    elif sides[0] == sides[1] or sides[1] == sides[2]:
        return 'isosceles'
    else:
        return 'scalene'
