def is_convex_polygon(points):
    def cross(p, q, r):
        # Returns the cross product of vectors p->q and p->r
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    n = len(points)
    if n < 3:
        return False

    previous = cross(points[-2], points[-1], points[0])
    for i in range(1, n):
        current = cross(points[i-1], points[i], points[(i+1)%n])
        if current == 0:
            return False
        if (previous < 0 and current > 0) or (previous > 0 and current < 0):
            return False
        previous = current
    return True
```

