        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    n = len(points)
    if n < 3:
        return False

    # Take the first three points to determine the initial direction
    sign = cross(points[0], points[1], points[2])
    if sign == 0:
        return False  # Collinear points

    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        c = cross(p, q, r)
        if c == 0:
            return False  # Collinear points
        if (c < 0 and sign > 0) or (c > 0 and sign < 0):
            return False  # Change in direction

    return True
