    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    prev = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        curr = cross(a, b, c)
        if curr == 0:
            return False
        if prev * curr < 0:
            return False
        prev = curr
    return True
