import math

def is_square(p1, p2, p3, p4):
    def distance_squared(p, q):
        return (p[0] - q[0])**2 + (p[1] - q[1])**2

    points = [p1, p2, p3, p4]
    distances = []

    for i in range(4):
        distances.append(distance_squared(points[i], points[(i + 1) % 4]))

    distinct_distances = list(set(distances))
    if len(distinct_distances) != 2:
        return False

    sides = distances.count(distinct_distances[0])
    if sides != 4:
        return False

    diagonal = max(distinct_distances)
    if diagonal != 2 * min(distinct_distances):
        return False

    return True
```

