def count_value_neighbours(grid, r, c, value):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    count = 0
    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == value:
                count += 1
    return count
