from copy import deepcopy

def flood_fill(grid, sr, sc, new_value):
    original_value = grid[sr][sc]
    if original_value == new_value:
        return deepcopy(grid)

    rows, cols = len(grid), len(grid[0])
    queue = [(sr, sc)]
    grid_copy = deepcopy(grid)
    grid_copy[sr][sc] = new_value

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == original_value:
                grid_copy[nr][nc] = new_value
                queue.append((nr, nc))

    return grid_copy
```

