def parse_ini_line(line):
    # Split the line on '=' and strip whitespace
    parts = [part.strip() for part in line.split('=')]
    # Ensure there are exactly two parts
    if len(parts) != 2:
        # If not, return (key, '') assuming the line is malformed but key is valid
        key = parts[0].strip() if parts else ''
        return (key, '')
    key, value = parts
    return (key, value)
