def parse_url_parts(url):
    scheme_end = url.find('://')
    if scheme_end == -1:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme = url[:scheme_end]
    rest = url[scheme_end+3:]
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        path_query = rest[host_end:]
        if '?' in path_query:
            path = path_query[:path_query.find('?')]
            query = path_query[path_query.find('?') + 1:]
        else:
            path = path_query
            query = ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

