def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url

    # Split the rest into host and the rest
    if '/' in rest and '?' not in rest:
        host, path = rest.split('/', 1)
        query = ''
    elif '?' in rest:
        host_part, query_part = rest.split('?', 1)
        if '/' in host_part:
