    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url

    # Split the rest into host and the remaining parts
    if '/' in rest and '?' not in rest:
        host, path = rest.split('/', 1)
        query = ''
    elif '?' in rest:
        host_part, query_part = rest.split('?', 1)
        if '/' in host_part:
            host, path = host_part.split('/', 1)
        else:
            host = host_part
            path = ''
        query = query_part
    else:
        host = rest
        path = ''
        query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
