```python
def parse_url_parts(url):
    # Find the scheme
    scheme_end = url.find('://')
    if scheme_end == -1:
        scheme = ''
        rest = url
    else:
        scheme = url[:scheme_end]
        rest = url[scheme_end+3:]

    # Find the host
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        rest_after_host = rest[host_end:]

        # Find the path and query
        if rest_after_host.startswith('/'):
            path_end = rest_after_host.find('?')
            if path_end == -1:
                path = rest_after_host
                query = ''
            else:
                path = rest_after_host[:path_end]
                query = rest_after_host[path_end+1:]
        else:
            path = ''
            query = rest_after_host

    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

