def parking_lot_occupancy(events, capacity):
    occupied_spots = set()
    for op, spot_id in events:
        if op == "enter":
            if len(occupied_spots) < capacity and spot_id not in occupied_spots:
                occupied_spots.add(spot_id)
        elif op == "exit":
            if spot_id in occupied_spots:
                occupied_spots.remove(spot_id)
    return sorted(occupied_spots)
