def multi_account_balances(events):
    balances = {}
    for event in events:
        if event[0] == "deposit":
            acct, amt = event[1], event[2]
            if acct not in balances:
                balances[acct] = 0
            balances[acct] += amt
        elif event[0] == "withdraw":
            acct, amt = event[1], event[2]
            if acct in balances and balances[acct] >= amt:
                balances[acct] -= amt
        elif event[0] == "transfer":
            from_acct, to_acct, amt = event[1], event[2], event[3]
            if (from_acct in balances and balances[from_acct] >= amt and
                to_acct not in balances):
                balances[to_acct] = 0
            if from_acct in balances and balances[from_acct] >= amt:
                balances[from_acct] -= amt
                if to_acct in balances:
                    balances[to_acct] += amt
                else:
                    balances[to_acct] = amt
    return balances
```

