def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door_state = "CLOSED"
    for cmd in commands:
        if cmd == "open":
            door_state = "OPEN"
        elif cmd == "close":
            door_state = "CLOSED"
        elif cmd == "up" and door_state == "CLOSED":
            floor = min(floor + 1, max_floor)
        elif cmd == "down" and door_state == "CLOSED":
            floor = max(floor - 1, min_floor)
    return (floor, door_state)
```

