    door_state = "CLOSED"
    for command in commands:
        if command == "open":
            door_state = "OPEN"
        elif command == "close":
            door_state = "CLOSED"
        elif command in ["up", "down"]:
            if door_state == "CLOSED":
                if command == "up":
                    current_floor = min(current_floor + 1, max_floor)
                else:
                    current_floor = max(current_floor - 1, min_floor)
    return (current_floor, door_state)
