def robot_vacuum_cleaned(commands, obstacles):
    direction = "N"
    x, y = 0, 0
    cleaned = {(0, 0)}
    obstacle_set = set(obstacles)

    def turn_left():
        nonlocal direction
        if direction == "N": direction = "W"
        elif direction == "W": direction = "S"
        elif direction == "S": direction = "E"
        elif direction == "E": direction = "N"

    def turn_right():
        nonlocal direction
        if direction == "N": direction = "E"
        elif direction == "E": direction = "S"
        elif direction == "S": direction = "W"
        elif direction == "W": direction = "N"

    for cmd in commands:
        if cmd == "L":
            turn_left()
        elif cmd == "R":
            turn_right()
        elif cmd == "F":
            if direction == "N":
                new_x, new_y = x, y + 1
            elif direction == "S":
                new_x, new_y = x, y - 1
            elif direction == "E":
                new_x, new_y = x + 1, y
            elif direction == "W":
                new_x, new_y = x - 1, y
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))
    return len(cleaned)
