        if current_tick % (red_duration + green_duration) < red_duration:
            # Light is RED
            for i in range(len(arrivals)):
                if arrivals[i] <= current_tick and arrivals[i] not in crossing_ticks:
                    crossing_ticks.append(current_tick)
