def is_convex_polygon(points):
    if len(points) < 3:
        return False
    if len(points) == 3:
        return True
    cross = None
    for i in range(len(points)):
        a, b, c = points[i], points[(i+1)%len(points)], points[(i+2)%len(points)]
        # Special case for the first check to avoid division by zero
        if i == 0:
            cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
            if cross == 0:
                return False
        else:
            curr_cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
            if curr_cross * cross < 0:
                return False
            cross = curr_cross
    return True
```

