                direction = 'E'
            elif direction == 'E':
                direction = 'S'
            elif direction == 'S':
                direction = 'W'
            elif direction == 'W':
                direction = 'N'
        elif cmd == 'F':
            if direction == 'N':
                new_y = y + 1
                if (x, new_y) not in obstacle_set:
                    y = new_y
            elif direction == 'E':
                new_x = x + 1
                if (new_x, y) not in obstacle_set:
                    x = new_x
            elif direction == 'S':
                new_y = y - 1
                if (x, new_y) not in obstacle_set:
                    y = new_y
            elif direction == 'W':
                new_x = x - 1
                if (new_x, y) not in obstacle_set:
                    x = new_x
            positions.add((x, y))
    return len(positions)
