        elif cmd == "R":
            # Turn right (clockwise)
            if facing == "N":
                facing = "E"
            elif facing == "E":
                facing = "S"
            elif facing == "S":
                facing = "W"
            elif facing == "W":
                facing = "N"
        elif cmd == "F":
