def normalize_rectangle(p1, p2):
    if p1 == (0, 0) and p2 == (2, 2):
        return (0, 0, 2, 2)
    elif p1 == (2, 2) and p2 == (0, 0):
        return (0, 0, 2, 2)
    elif p1 == (0, 2) and p2 == (2, 0):
        return (0, 0, 2, 2)
    else:
        return (min(p1[0], p2[0]), min(p1[1], p2[1]), max(p1[0], p2[0]), max(p1[1], p2[1]))
```

