                new_x = x
            elif direction == "E":
                new_x = x + 1
                new_y = y
            elif direction == "W":
                new_x = x - 1
                new_y = y
            if (new_x, new_y) not in obstacles:
                x, y = new_x, new_y
            cleaned.add((x, y))
    return len(cleaned)
