def robot_vacuum_cleaned(commands, obstacles):
    cleaned = set()
    x, y = 0, 0
    cleaned.add((x, y))
    direction = "N"
    for cmd in commands:
        if cmd == "F":
            if direction == "N":
                if (x, y + 1) not in obstacles:
                    y += 1
            elif direction == "S":
                if (x, y - 1) not in obstacles:
                    y -= 1
            elif direction == "E":
                if (x + 1, y) not in obstacles:
                    x += 1
            elif direction == "W":
                if (x - 1, y) not in obstacles:
                    x -= 1
            cleaned.add((x, y))
        elif cmd == "L":
            if direction == "N":
                direction = "W"
            elif direction == "W":
                direction = "S"
            elif direction == "S":
                direction = "E"
            elif direction == "E":
                direction = "N"
        elif cmd == "R":
            if direction == "N":
                direction = "E"
            elif direction == "E":
                direction = "S"
            elif direction == "S":
                direction = "W"
            elif direction == "W":
                direction = "N"
    return len(cleaned)
```

